import asyncio, os, signal, sys, threading, time
sys.path.insert(0, "/app")

SEM = None
async def job(i, use_sem):
    async def body():
        try:
            await asyncio.sleep(100)
        finally:
            print(f"FIN-ENTER {i}", flush=True)
            try:
                await asyncio.sleep(0.05)
            except BaseException as e:
                print(f"FIN-RAISED {i}: {type(e).__name__}", flush=True); raise
            print(f"CLEANED {i}", flush=True)
    if use_sem:
        async with SEM:
            await body()
    else:
        await body()

async def main(use_sem):
    global SEM
    SEM = asyncio.Semaphore(3)
    tasks = [asyncio.ensure_future(job(i, use_sem)) for i in range(3)]
    try:
        await asyncio.gather(*tasks)
    except BaseException:
        for t in tasks: t.cancel()
        pending = [t for t in tasks if not t.done()]
        while pending:
            try: await asyncio.wait(pending)
            except asyncio.CancelledError: pass
            pending = [t for t in tasks if not t.done()]
        raise

use_sem = sys.argv[1] == "sem"
def send():
    time.sleep(1.0); os.kill(os.getpid(), signal.SIGINT)
threading.Thread(target=send, daemon=True).start()
try: asyncio.run(main(use_sem))
