import asyncio, os, signal, sys, threading, time

async def job(i):
    try:
        await asyncio.sleep(100)
    finally:
        for s in range(5):
            try:
                await asyncio.sleep(0.02)
            except BaseException as e:
                print(f"[job{i}] step{s} raised {type(e).__name__}", flush=True); raise
        print(f"[job{i}] CLEANED", flush=True)

async def run_tasks(makers, maxc):
    sem = asyncio.Semaphore(maxc)
    async def one(m):
        async with sem:
            await m()
    running = [asyncio.ensure_future(one(m)) for m in makers]
    # Wait via a shielded gather so outer cancellations don't reach the jobs.
    waiter = asyncio.gather(*running)
    try:
        await asyncio.shield(waiter)
    except BaseException:
        for j in running:
            if not j.done(): j.cancel()
        # drain, swallowing cancellations to us, until all jobs done
        pending=[j for j in running if not j.done()]
        while pending:
            try: await asyncio.shield(asyncio.gather(*pending, return_exceptions=True))
            except asyncio.CancelledError: pass
            pending=[j for j in running if not j.done()]
        raise

async def main():
    await run_tasks([lambda i=i: job(i) for i in range(2)], 2)

def interrupt():
    time.sleep(1.0); print("[t] SIGINT #1", flush=True); os.kill(os.getpid(), signal.SIGINT)
    time.sleep(0.03); print("[t] SIGINT #2", flush=True); os.kill(os.getpid(), signal.SIGINT)
threading.Thread(target=interrupt, daemon=True).start()
try: asyncio.run(main())
except KeyboardInterrupt: print("[top] KBI", flush=True)
